// Writes the keys of when clauses, from when.json, as Go for the manifest check and as TypeScript
// for the SDK. Run by `make lib_protocol_generate`; the generated files are committed.
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const read = (path) => readFileSync(fileURLToPath(new URL(path, import.meta.url)), 'utf8')
const write = (path, text) => writeFileSync(fileURLToPath(new URL(path, import.meta.url)), text)

const { keys } = JSON.parse(read('../when.json'))
const HEADER =
  'Code generated by libs/protocol/tools/when.mjs from libs/protocol/when.json. DO NOT EDIT.'
const names = keys.map((one) => one.name)

const go = [
  `// ${HEADER}`,
  '',
  'package when',
  '',
  '// keyList is the keys a condition may name, for the text of an error.',
  `const keyList = ${JSON.stringify(names.join(', '))}`,
  '',
  '// IsKey reports whether a condition may name the key.',
  'func IsKey(name string) bool {',
  '\tswitch name {',
  `\tcase ${names.map((name) => JSON.stringify(name)).join(', ')}:`,
  '\t\treturn true',
  '\t}',
  '\treturn false',
  '}',
  '',
].join('\n')

const ts = [
  `// ${HEADER}`,
  '',
  '// WHEN_KEYS are the keys a condition may name.',
  `export const WHEN_KEYS = [${names.map((name) => `'${name}'`).join(', ')}] as const`,
  '',
  '// WhenKey is a key a condition may name.',
  'export type WhenKey = (typeof WHEN_KEYS)[number]',
  '',
].join('\n')

write('../../plugin-catalog/when/keys.go', go)
write('../../plugin-sdk-ts/src/slots/whenKeys.ts', ts)
